-- =====================================================================
-- Datos de prueba ANONIMIZADOS (DML). Una sola transaccion.
-- Requiere: database/schema-consorcios.sql y database/amenities.sql aplicados.
-- Carga 4 consorcios demo, unidades, personas, vinculaciones, gastos,
-- liquidaciones y pagos. Para los amenities, ejecutar despues
-- database/datos-prueba-amenities.sql.
--
-- Las cuentas @demo.test se crean SIN contraseña utilizable ('!sin-clave'
-- no es un hash valido, por lo que no permiten iniciar sesion). Para
-- habilitarlas, al terminar ejecutar (reemplazando <contraseña>):
--   update dbo.usuarios
--      set passwordhash = extensions.crypt('<contraseña>', extensions.gen_salt('bf', 10))
--    where email like '%@demo.test';
-- (en un PostgreSQL local sin el esquema "extensions", usar crypt() y gen_salt()).
-- =====================================================================
begin;
-- Personas pertenecen a un consorcio: se permite NULL durante la carga y se completa mas abajo.
alter table dbo.personas alter column consorcioid drop not null;
-- Distribucion de prueba de los administradores fijos (varios consorcios, uno, ninguno):
--   admin1: Demo 1 y Demo 2 | admin2: Demo 3 | admin3: ninguno | admin4: Demo 4
delete from dbo.usuariosconsorcios where usuarioid in (select id from dbo.usuarios where email in ('admin1@demo.test','admin2@demo.test','admin3@demo.test','admin4@demo.test'));
select u.id, c.id from dbo.usuarios u join dbo.consorcios c on
  (u.email = 'admin1@demo.test' and c.nombre in ('Consorcio Demo 1','Consorcio Demo 2'))
  or (u.email = 'admin2@demo.test' and c.nombre = 'Consorcio Demo 3')
  or (u.email = 'admin4@demo.test' and c.nombre = 'Consorcio Demo 4');
-- Admin y superadmin no son personas: se desvinculan y se borran sus personas.
update dbo.usuarios set personaid = null where rol in ('SUPERADMINISTRADOR', 'ADMINISTRADOR_CONSORCIO');
-- Personas sin unidad vinculada (incluye las de cuentas PROPIETARIO/INQUILINO sin unidad): desvincular y borrar.
update dbo.usuarios set personaid = null where personaid in (select p.id from dbo.personas p where not exists (select 1 from dbo.vinculacionesunidad v where v.personaid = p.id));
delete from dbo.personas p where not exists (select 1 from dbo.vinculacionesunidad v where v.personaid = p.id);
-- Una persona pertenece a UN consorcio: si estaba vinculada a unidades de varios, se crea una copia por consorcio.
create temp table tmp_pm on commit drop as
select v.personaid, uf.consorcioid,
       row_number() over (partition by v.personaid order by min(v.fechainicio), uf.consorcioid) as rn,
       gen_random_uuid() as nuevo
from dbo.vinculacionesunidad v
join dbo.unidadesfuncionales uf on uf.id = v.unidadfuncionalid
group by v.personaid, uf.consorcioid;
update dbo.personas p set consorcioid = m.consorcioid from tmp_pm m where m.personaid = p.id and m.rn = 1;
select m.nuevo, m.consorcioid, p.nombre, p.apellido, p.dni, p.email, p.telefono
from tmp_pm m join dbo.personas p on p.id = m.personaid where m.rn > 1;
update dbo.vinculacionesunidad v set personaid = m.nuevo
from tmp_pm m, dbo.unidadesfuncionales uf
where uf.id = v.unidadfuncionalid and m.personaid = v.personaid and m.consorcioid = uf.consorcioid and m.rn > 1;
alter table dbo.personas alter column consorcioid set not null;
commit;
select (select count(*) from dbo.personas) personas,(select count(*) from dbo.consorcios) consorcios,(select count(*) from dbo.usuarios) usuarios,(select count(*) from dbo.unidadesfuncionales) unidades,(select count(*) from dbo.vinculacionesunidad) vinculaciones,(select count(*) from dbo.gastos) gastos,(select count(*) from dbo.liquidaciones) liquidaciones,(select count(*) from dbo.liquidacionesunidad) liq_unidad;
